-- Keep existing RLS: clients only receive records their membership can read.
do $$ begin if exists(select 1 from pg_publication where pubname='supabase_realtime') then if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='staff_time_entries') then alter publication supabase_realtime add table public.staff_time_entries; end if; if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='staff_leave_requests') then alter publication supabase_realtime add table public.staff_leave_requests; end if; end if; end $$;
